import numpy as np


def q155(parameters, evaluate):
    import itertools

    names = list(parameters)
    best = None
    score = -np.inf
    for values in itertools.product(*(parameters[n] for n in names)):
        config = dict(zip(names, values))
        current = float(evaluate(config))
        if current > score:
            best, score = (config, current)
    return (best, score)
